def json_pointer_get(document, pointer):
    if not pointer:
        return document
    current = document
    for raw in pointer.lstrip('/').split('/'):
        key = raw.replace('~1', '/').replace('~0', '~')
        current = current[int(key)] if isinstance(current, list) else current[key]
    return current

