def topological_batches(graph):
    pending = {key: set(value) for key, value in graph.items()}
    output = []
    while pending:
        ready = sorted(key for key, deps in pending.items() if not deps)
        if not ready:
            break
        output.append(ready)
        for key in ready:
            pending.pop(key)
        for deps in pending.values():
            deps.difference_update(ready)
    return output

